func agreementCoupledCodeP2Projection(before, after []agreementFailure, old, private string) bool {
	want := maps.Clone(agreementMixedCurrent(before))
	p1, p2 := 0, 0
	for fi := range before {
		f := before[fi]
		if f.Tuple.Target != old {
			continue
		}
		if f.Tuple.SourceRole != "" || f.Tuple.Section != "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound || f.Multiplicity != 1 {
			return false
		}
		switch {
		case f.Property == "P1" && f.Identity == "citation-occurrences" && f.Direction == "page-only" && f.Tuple.State == "":
			p1++
		case f.Property == "P2" && f.Identity == "wikilink-in-code" && f.Direction == "page-in-code" && f.Tuple.State == "wikilink-broken":
			p2++
		default:
			return false
		}
		delete(want, agreementSignature(&f))
		f.Tuple.Target = private
		want[agreementSignature(&f)]++
	}
	return p1 == 1 && p2 == 1 && maps.Equal(want, agreementMixedCurrent(after))
}

