func TestAgreementCoupledCodeP2OwnedRefusals(t *testing.T) {
	r := agreementCoupledCodeP2DeclarationReading()
	if r == nil {
		t.Fatal("caught: complete coupled code refusal declaration")
	}
	for fi := range r.Before {
		f := r.Before[fi]
		if agreementSignature(&f) != r.Selected {
			continue
		}
		for _, c := range []agreementCase{{Body: r.Body + "unowned"}, {Body: r.Body, Title: "unowned"}, {Body: r.Body, Companions: capturedBodies{"A.md": "unowned"}}} {
			if k, _, _ := agreementCoupledCodeP2Difference(c, &f, r.HTML, &r.Page, r.Diagnostics, r.Before); k != "" {
				t.Fatal("caught: coupled code borrowed source or vault")
			}
		}
		for _, change := range []func(*agreementFailure){func(f *agreementFailure) { f.Property = "P1" }, func(f *agreementFailure) { f.Identity = "unowned" }, func(f *agreementFailure) { f.Direction = "unowned" }, func(f *agreementFailure) { f.Tuple.Target = "unowned" }, func(f *agreementFailure) { f.Tuple.Section = "unowned" }, func(f *agreementFailure) { f.Tuple.State = "unowned" }, func(f *agreementFailure) { f.Tuple.SourceRole = "unowned" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Fragment = "unowned" }, func(f *agreementFailure) { f.Cut = "unowned" }, func(f *agreementFailure) { f.PagePresent = true }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }} {
			mutated := f
			change(&mutated)
			if k, _, _ := agreementCoupledCodeP2Difference(agreementCase{Body: r.Body}, &mutated, r.HTML, &r.Page, r.Diagnostics, r.Before); k != "" {
				t.Fatal("caught: coupled code borrowed signed observation")
			}
		}
		changedPage := r.Page
		changedPage.Citations = nil
		if k, _, _ := agreementCoupledCodeP2Difference(agreementCase{Body: r.Body}, &f, r.HTML, &changedPage, r.Diagnostics, r.Before); k != "" {
			t.Fatal("caught: coupled code borrowed public ledger")
		}
		if k, _, _ := agreementCoupledCodeP2Difference(agreementCase{Body: r.Body}, &f, r.HTML, &r.Page, nil, r.Before); k != "" {
			t.Fatal("caught: coupled code borrowed diagnostic ledger")
		}
		if k, _, _ := agreementCoupledCodeP2Difference(agreementCase{Body: r.Body}, &f, r.HTML, &r.Page, r.Diagnostics, r.Before[:1]); k != "" {
			t.Fatal("caught: coupled code borrowed signed pool")
		}
	}
}

