func TestAgreementCoupledCodeP2OwnedProjectionRefusals(t *testing.T) {
	r := agreementCoupledCodeP2DeclarationReading()
	if r == nil {
		t.Fatal("caught: complete coupled code projection refusal declaration")
	}
	var oldP1, oldP2, privateP1, privateP2 []agreementFailure
	for i := range r.Before {
		f := r.Before[i]
		switch f.Property {
		case "P1":
			oldP1 = append(oldP1, f)
		case "P2":
			oldP2 = append(oldP2, f)
		}
	}
	for i := range r.After {
		f := r.After[i]
		switch f.Property {
		case "P1":
			privateP1 = append(privateP1, f)
		case "P2":
			privateP2 = append(privateP2, f)
		}
	}
	if len(oldP1) != 1 || len(oldP2) != 1 || len(privateP1) != 1 || len(privateP2) != 1 {
		t.Fatal("caught: complete coupled independent property declarations")
	}
	if agreementCoupledCodeP2Projection(oldP2, privateP2, "image.png", "qqqqqqqqq") {
		t.Fatal("caught: coupled code cannot borrow an absent P1 declaration")
	}
	if agreementCoupledCodeP2Projection(oldP1, privateP1, "image.png", "qqqqqqqqq") {
		t.Fatal("caught: coupled code cannot borrow an absent P2 declaration")
	}
	changed := append([]agreementFailure{}, r.After...)
	changed[0].Multiplicity++
	if agreementCoupledCodeP2Projection(r.Before, changed, "image.png", "qqqqqqqqq") {
		t.Fatal("caught: coupled code cannot borrow a changed private multiplicity")
	}
}
func TestAgreementCoupledCodeP2OwnedPhysicalRefusals(t *testing.T) {
	r := agreementCoupledCodeP2DeclarationReading()
	if r == nil {
		t.Fatal("caught: complete coupled code physical refusal declaration")
	}
	for i := range r.Before {
		f := r.Before[i]
		if agreementSignature(&f) != r.Selected {
			continue
		}
		for _, change := range []func(*agreementFailure){func(f *agreementFailure) { f.Property = "P1" }, func(f *agreementFailure) { f.Identity = "unowned" }, func(f *agreementFailure) { f.Direction = "unowned" }, func(f *agreementFailure) { f.Tuple.Target = "unowned" }, func(f *agreementFailure) { f.Tuple.Section = "unowned" }, func(f *agreementFailure) { f.Tuple.State = "unowned" }, func(f *agreementFailure) { f.Tuple.SourceRole = "unowned" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Fragment = "unowned" }, func(f *agreementFailure) { f.Cut = "unowned" }, func(f *agreementFailure) { f.PagePresent = true }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }} {
			mutated := f
			change(&mutated)
			if _, _, valid := agreementCoupledCodeP2Physical(r.Body, r.HTML, &mutated); valid {
				t.Fatal("caught: coupled code physical owner borrowed another signed property")
			}
		}
	}
}

func TestAgreementCoupledCodeP2OwnedCheckTargets(t *testing.T) {
	r := agreementCoupledCodeP2DeclarationReading()
	if r == nil {
		t.Fatal("caught: complete coupled code check-target declaration")
	}
	if !cmp.Equal(judge.LinkTargets(r.Body), r.Check.Targets) || !cmp.Equal(judge.LinkTargets(r.Private), r.PrivateCheck.Targets) || !cmp.Equal(r.Check.Targets, r.PrivateCheck.Targets) {
		t.Fatal("caught: whole coupled code original and private product check-target ledgers")
	}
}
